// Android — hardware-backed AES key, with the StrongBox fallback people forget
fun ensureAesKey(alias: String) {
  val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
  if (ks.containsAlias(alias)) return

  fun spec(strongBox: Boolean) = KeyGenParameterSpec.Builder(
    alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
  )
    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
    .setKeySize(256)
    .setUserAuthenticationRequired(false)       // true gates every use behind biometrics
    .setIsStrongBoxBacked(strongBox)
    .build()

  val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
  try {
    gen.init(spec(true)); gen.generateKey()
  } catch (e: StrongBoxUnavailableException) {
    gen.init(spec(false)); gen.generateKey()    // most devices land here
  }
}

// AES-GCM: keep the IV with the ciphertext, and never reuse one under the same key
fun encrypt(plain: ByteArray, alias: String): EncryptedBlob {
  val key = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }.getKey(alias, null)
  val cipher = Cipher.getInstance("AES/GCM/NoPadding").apply { init(Cipher.ENCRYPT_MODE, key) }
  return EncryptedBlob(iv = cipher.iv, ciphertext = cipher.doFinal(plain))
}

