// One consent gate — nothing non-essential may start before the user answers
class SdkGate(private val consent: ConsentStore) {
  fun onConsentResolved(c: Consent) {
    if (c.analytics) AnalyticsSdk.start()
    if (c.crash) CrashSdk.start()
    if (c.marketing) MarketingSdk.start()
  }
}

